package com.zeeshan.jobtrack.service;
import com.zeeshan.jobtrack.dto.JobDtos.*; import com.zeeshan.jobtrack.entity.*; import com.zeeshan.jobtrack.repository.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class JobService { private final JobApplicationRepository repo; private final UserRepository users; public JobService(JobApplicationRepository r,UserRepository u){repo=r;users=u;}
 public PageResponse<JobResponse> list(UUID uid,int page,int size,String sort){Sort s=Sort.by(Sort.Direction.DESC,"updatedAt"); if("oldest".equalsIgnoreCase(sort))s=Sort.by(Sort.Direction.ASC,"updatedAt"); Page<JobApplication> p=repo.findByUserId(uid,PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100),s));return new PageResponse<>(p.getContent().stream().map(this::map).toList(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());}
 public JobResponse get(UUID uid,UUID id){return map(repo.findByIdAndUserId(id,uid).orElseThrow(()->new NoSuchElementException("Job not found")));}
 public JobResponse create(UUID uid,JobRequest r){JobApplication j=new JobApplication();j.setUser(users.findById(uid).orElseThrow());apply(j,r);return map(repo.save(j));}
 public JobResponse update(UUID uid,UUID id,JobRequest r){JobApplication j=repo.findByIdAndUserId(id,uid).orElseThrow(()->new NoSuchElementException("Job not found"));apply(j,r);return map(repo.save(j));}
 public void delete(UUID uid,UUID id){JobApplication j=repo.findByIdAndUserId(id,uid).orElseThrow(()->new NoSuchElementException("Job not found"));repo.delete(j);}
 public DashboardResponse dashboard(UUID uid){long total=repo.countByUserId(uid),saved=repo.countByUserIdAndStatus(uid,JobStatus.SAVED),applied=repo.countByUserIdAndStatus(uid,JobStatus.APPLIED),screen=repo.countByUserIdAndStatus(uid,JobStatus.SCREENING),inter=repo.countByUserIdAndStatus(uid,JobStatus.INTERVIEW),offers=repo.countByUserIdAndStatus(uid,JobStatus.OFFER),rej=repo.countByUserIdAndStatus(uid,JobStatus.REJECTED);return new DashboardResponse(total,saved,applied,screen,inter,offers,rej,total-rej-repo.countByUserIdAndStatus(uid,JobStatus.WITHDRAWN));}
 private void apply(JobApplication j,JobRequest r){j.setCompany(r.company().trim());j.setPosition(r.position().trim());j.setLocation(r.location());j.setWorkMode(r.workMode()==null?WorkMode.FLEXIBLE:r.workMode());j.setStatus(r.status()==null?JobStatus.SAVED:r.status());j.setPriority(r.priority()==null?JobPriority.MEDIUM:r.priority());j.setSource(r.source());j.setJobUrl(r.jobUrl());j.setSalary(r.salary());j.setRecruiterName(r.recruiterName());j.setRecruiterEmail(r.recruiterEmail());j.setAppliedDate(r.appliedDate());j.setDeadline(r.deadline());j.setNextFollowUpDate(r.nextFollowUpDate());j.setNotes(r.notes());}
 private JobResponse map(JobApplication j){return new JobResponse(j.getId(),j.getCompany(),j.getPosition(),j.getLocation(),j.getWorkMode(),j.getStatus(),j.getPriority(),j.getSource(),j.getJobUrl(),j.getSalary(),j.getRecruiterName(),j.getRecruiterEmail(),j.getAppliedDate(),j.getDeadline(),j.getNextFollowUpDate(),j.getNotes(),j.getCreatedAt(),j.getUpdatedAt());}
}
